// Development-only translation of the pinned HCL Ragel tables, not a Go transpiler.
// Run: node src/hclsyntax/generate-scanner.mjs <hcl checkout>
// oxlint-disable-next-line rules/no-node-imports -- This development generator reads Go sources and writes the TypeScript tables with Node.
import { readFile, writeFile } from 'node:fs/promises';
// oxlint-disable-next-line rules/no-node-imports -- Resolve local checkout and generated file paths in the native Node CLI.
import path from 'node:path';

const { resolve } = path;
const firstArgument = 2;
const hcl = process.argv[firstArgument];
// oxlint-disable-next-line rules/force-predicate, rules/force-string-empty -- The generator is directly runnable with Node before installing repository dependencies.
if (hcl === undefined || hcl === '') {
  // oxlint-disable-next-line rules/require-tagged-error -- Report a missing CLI argument with the generator's existing native error.
  throw new Error('Pass the pinned HCL source directory');
}
const revision = '00057cf06d7b38a3f89e6e54d622eee98322b314';
const mpl = `/*! @license MPL-2.0\n * Copyright IBM Corp. 2014, 2025\n * Translated source: https://github.com/hashicorp/hcl/tree/${revision}\n * Covered source and modifications are available in this Reylo fork. See licenses/hashicorp-hcl-MPL-2.0.txt.\n */`;
const tablePattern = /var (?<name>_\w+) \[\](?<storage>\w+) = \[\]\w+\{(?<entries>[\s\S]*?)\n\}/gu;
const constantPattern = /const (?<name>\w+) int = (?<value>\d+)/gu;
const tableStorage = new Map([
  ['byte', 'Uint8Array'],
  ['int16', 'Int16Array'],
  ['uint16', 'Uint16Array'],
]);

/** @type {(input: string, prefix: string) => string} */
const formatTables = (input, prefix) => {
  const trimmedPrefix = prefix.length + '_'.length;
  return Array.from(input.matchAll(tablePattern), ({ groups }) => {
    if (groups?.name?.startsWith(prefix) !== true) {return '';}
    const { name, storage, entries } = groups;
    const kind = tableStorage.get(storage ?? '') ?? 'Int32Array';
    return `export const ${name.slice(trimmedPrefix)} = new ${kind}([${entries}\n]);\n\n`;
  }).join('');
};

/** @type {(input: string) => string} */
const formatConstants = (input) =>
  Array.from(input.matchAll(constantPattern), ({ groups }) =>
    groups
      ? `export const ${groups.name.replace(/^hcltok_|^hclstrtok_/u, '')} = ${groups.value};\n`
      : '',
  ).join('');

/** @type {(inputFile: string, outputFile: string, prefix: string) => Promise<void>} */
const generate = async (inputFile, outputFile, prefix) => {
  const source = `hclsyntax/${inputFile}`;
  const input = await readFile(resolve(hcl, source), 'utf8');
  const notice = `${mpl}\n// HCL revision ${revision}, ${source}.`;
  const header = `${notice}\n// Generated by generate-scanner.mjs. Do not edit the transition tables.\n\n`;
  await writeFile(resolve(import.meta.dirname, outputFile), header + formatTables(input, prefix) + formatConstants(input));
};

await generate('scan_tokens.go', 'scanner-tables.ts', '_hcltok');
await generate('scan_string_lit.go', 'string-literal-tables.ts', '_hclstrtok');
